<script setup>
import { computed,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { Info,ShieldCheck,SquarePlus,Layers,Clock3,FileBadge,ArrowRight } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import PageTitle from '../components/PageTitle.vue'
import StatusBadge from '../components/StatusBadge.vue'
import FileUpload from '../components/FileUpload.vue'
import { state } from '../lib/store'
import { confirm,notify,requireRole } from '../lib/actions'
const route=useRoute(),router=useRouter(),tab=ref(route.query.tab==='business'?'business':'personal'),model=ref({company:'',credit:'',name:'',contact:'',id:''}),files=ref([]),agreed=ref(false),form=ref(null),sampled=ref(false)
watch(()=>route.query.tab,v=>{if(v==='personal'||v==='business')tab.value=v})
watch(tab,()=>{agreed.value=false;sampled.value=false;model.value={company:'',credit:'',name:'',contact:'',id:''};files.value=[]})
const status=computed(()=>state.auth[tab.value])
function sample(){sampled.value=true;model.value={company:'来单啦演示企业（非真实主体）',credit:'DEMO-COMPANY',name:'演示用户',contact:'演示联系方式',id:'DEMO-IDENTITY'};files.value=[{uid:'license-demo',name:'营业执照示意（非真实证件）',type:'document',size:1000}];notify('已填入虚构的演示信息，不包含真实证件资料')}
function submit(){if(!requireRole(router,state.session.role))return;if(!agreed.value){ElMessage.warning('请勾选信息确认');return}if(!sampled.value){ElMessage.warning('此处不采集真实证件，请点击“填入演示信息”体验认证流程');return}if(tab.value==='business'&&(!model.value.company||!model.value.credit||!model.value.name||!model.value.contact||!files.value.length)||tab.value==='personal'&&(!model.value.name||!model.value.id)){ElMessage.warning('请补全演示字段');return}state.auth[tab.value]='审核中';model.value={company:'',credit:'',name:'',contact:'',id:''};files.value=[];notify('演示认证状态已提交为审核中；未进行真实核验')}
async function pass(){if(await confirm('仅将当前浏览器中的身份标记为“演示已认证”，用于体验接单或发布流程，不代表真实认证。','体验认证通过状态')){state.auth[tab.value]='演示已认证';notify('演示认证状态已更新');const redirect=route.query.redirect;if(typeof redirect==='string'&&redirect.startsWith('/')&&!redirect.startsWith('//'))router.push(redirect)}}
</script>
<template><div><PageTitle title="认证中心" description="完成身份认证，让每一次合作更有保障。"/><el-tabs v-model="tab"><el-tab-pane label="实名认证" name="personal"/><el-tab-pane label="企业认证" name="business"/></el-tabs><div class="info-note" style="margin-bottom:20px"><Info/>{{tab==='business'?'发布任务前，请先完成企业认证。':'承接任务前，请先完成实名认证。'}}当前仅体验认证流程，请勿提交真实证件。</div><div class="columns wide-left"><section class="panel"><template v-if="status==='未认证'"><el-steps v-if="tab==='business'" :active="0" align-center><el-step title="上传营业执照"/><el-step title="填写企业信息"/><el-step title="提交审核"/></el-steps><div class="verify-form-layout" :class="{'personal-form':tab==='personal'}"><div v-if="tab==='business'"><div class="license-placeholder"><FileBadge :size="68"/><span>营业执照示意</span></div><FileUpload v-model="files" :limit="1" images-only label="选择执照示例"/><p class="field-help">演示页面不进行证件识别或真实信息上传。</p></div><el-form ref="form" :model="model" label-position="top"><template v-if="tab==='business'"><el-form-item label="企业名称" required><el-input v-model="model.company" placeholder="请输入营业执照上的企业名称" maxlength="80"/></el-form-item><el-form-item label="统一社会信用代码" required><el-input v-model="model.credit" placeholder="演示请使用下方虚构信息" maxlength="30"/></el-form-item></template><el-form-item :label="tab==='business'?'法人姓名':'姓名'" required><el-input v-model="model.name" placeholder="演示姓名" maxlength="20"/></el-form-item><el-form-item v-if="tab==='personal'" label="身份证号" required><el-input v-model="model.id" placeholder="不填写真实号码，请使用演示信息" maxlength="30"/></el-form-item><el-form-item v-else label="联系方式" required><el-input v-model="model.contact" placeholder="演示联系方式" maxlength="30"/></el-form-item><el-checkbox v-model="agreed">我确认正在使用虚构演示资料，不提交真实身份信息。</el-checkbox><div class="inline-actions" style="margin-top:22px"><el-button @click="sample">填入演示信息</el-button><el-button type="primary" :disabled="!agreed" @click="submit">提交认证（演示）</el-button></div><p class="field-help">输入信息不会保存在浏览器存储中，仅保存演示认证状态。</p></el-form></div></template><div v-else class="verify-result"><ShieldCheck :size="64"/><h2>{{status==='审核中'?'演示认证审核中':'演示认证已通过'}}</h2><p>当前未连接真实认证服务，不代表平台实名认证或企业资质核验。</p><el-button v-if="status==='审核中'" type="primary" @click="pass">体验认证通过状态</el-button><el-button v-else type="primary" @click="router.push(tab==='business'?'/publish/template':'/tasks')">{{tab==='business'?'去发布任务':'去寻找任务'}}<ArrowRight/></el-button><el-button link style="margin-top:20px" @click="state.auth[tab]='未认证'">重新体验认证表单</el-button></div></section><aside class="panel"><div class="panel-title"><h2>当前状态</h2><StatusBadge :status="status"/></div><div class="divider"/><h3>完成认证后，你可以：</h3><div class="verification-benefits"><div><SquarePlus/><span><strong>{{tab==='business'?'发布需求':'承接任务'}}</strong><small>与合适的伙伴开启合作</small></span></div><div><ShieldCheck/><span><strong>担保交易</strong><small>赏金托管，合作更有保障</small></span></div><div><Layers/><span><strong>订单管理</strong><small>统一查看进度与交付记录</small></span></div></div><div class="divider"/><p class="muted small"><Clock3 :size="15"/> 企业认证通常 4 小时内审核完成。</p></aside></div></div></template>
<style scoped>.verify-form-layout{display:grid;grid-template-columns:minmax(200px,.9fr) 1.4fr;gap:28px;align-items:start}.verify-form-layout.personal-form{grid-template-columns:1fr;max-width:560px;margin:15px auto}.license-placeholder{height:200px;border:1px dashed #c8d2e5;border-radius:8px;background:#f7f9fe;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:15px;color:#9ba9c0;margin-bottom:18px}.license-placeholder span{font-size:13px}.verification-benefits{display:grid;gap:25px;padding:10px 0}.verification-benefits>div{display:flex;gap:15px;align-items:center}.verification-benefits svg{color:#002bd7;background:#eef3ff;width:42px;height:42px;padding:10px;border-radius:7px}.verification-benefits strong{display:block;font-size:15px}.verification-benefits small{color:#8390a6;font-size:11px}.verify-result{min-height:440px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:30px}.verify-result>svg{color:#002bd7}.verify-result h2{margin:20px 0 8px}.verify-result p{font-size:13px;color:#8792a5;max-width:420px}.verify-result>.el-button{margin-top:20px}@media(max-width:1200px){.verify-form-layout{grid-template-columns:1fr}.license-placeholder{height:140px}}@media(max-width:650px){.verify-result{padding:20px 0}.verify-result h2{font-size:22px}}
</style>
